import { enqueue, getQueue, removeFromQueue } from './queueStore'

describe('queueStore', () => {
  beforeEach(() => {
    fakePreferences.clear()
  })

  it('starts empty', async () => {
    expect(await getQueue()).toEqual([])
  })

  it('enqueues and lists actions in insertion order', async () => {
    await enqueue({
      id: 'a', type: 'ping', queuedAt: 't1',
      payload: { recorded_at: 't1', latitude: 1, longitude: 1, idempotency_key: 'a' },
    })
    await enqueue({ id: 'b', type: 'complete_task', queuedAt: 't2', payload: { taskId: 'task-1' } })

    const queue = await getQueue()
    expect(queue.map((a) => a.id)).toEqual(['a', 'b'])
  })

  it('removes an action by id, leaving the rest untouched', async () => {
    await enqueue({ id: 'a', type: 'complete_task', queuedAt: 't1', payload: { taskId: 'task-1' } })
    await enqueue({ id: 'b', type: 'complete_task', queuedAt: 't2', payload: { taskId: 'task-2' } })

    await removeFromQueue('a')

    const queue = await getQueue()
    expect(queue.map((a) => a.id)).toEqual(['b'])
  })

  it('serializes concurrent enqueue calls so neither is lost', async () => {
    await Promise.all([
      enqueue({ id: 'x', type: 'complete_task', queuedAt: 't1', payload: { taskId: 'task-x' } }),
      enqueue({ id: 'y', type: 'complete_task', queuedAt: 't2', payload: { taskId: 'task-y' } }),
    ])

    const queue = await getQueue()
    expect(queue.map((a) => a.id).sort()).toEqual(['x', 'y'])
  })
