```ts
// tablet/src/location/locationStore.ts
import type { GeoLocation } from './backgroundLocation'

let latest: GeoLocation | null = null

export function setLatestLocation(location: GeoLocation | null): void {
  latest = location
}

export function getLatestLocation(): GeoLocation | null {
  return latest
}
