import { Preferences } from '@capacitor/preferences'

const REFRESH_TOKEN_KEY = 'atlas_refresh_token'

let currentAccessToken: string | null = null

export function setAccessToken(token: string | null): void {
  currentAccessToken = token
}

export function getAccessToken(): string | null {
  return currentAccessToken
}

export async function setRefreshToken(token: string | null): Promise<void> {
  if (token === null) {
    await Preferences.remove({ key: REFRESH_TOKEN_KEY })
  } else {
    await Preferences.set({ key: REFRESH_TOKEN_KEY, value: token })
  }
}

export async function getRefreshToken(): Promise<string | null> {
  const { value } = await Preferences.get({ key: REFRESH_TOKEN_KEY })
  return value
}

export async function setTokens(access: string | null, refresh: string | null): Promise<void> {
  setAccessToken(access)
  await setRefreshToken(refresh)
}

// tablet/src/location/backgroundLocation.ts
import { registerPlugin } from '@capacitor/core'

export interface GeoLocation {
  latitude: number
  longitude: number
  accuracy: number
  time: number | null
}

interface WatcherOptions {
  backgroundMessage?: string
  backgroundTitle?: string
  requestPermissions?: boolean
  stale?: boolean
  distanceFilter?: number
}

interface BackgroundGeolocationPlugin {
  addWatcher(
    options: WatcherOptions,
    callback: (position?: GeoLocation, error?: Error) => void,
  ): Promise<string>
  removeWatcher(options: { id: string }): Promise<void>
  openSettings(): Promise<void>
}

const BackgroundGeolocation = registerPlugin<BackgroundGeolocationPlugin>('BackgroundGeolocation')

export async function startWatching(onLocation: (location: GeoLocation) => void): Promise<string> {
  return BackgroundGeolocation.addWatcher(
    {
      backgroundMessage: 'Atlas Field Force is tracking your location for field visits.',
      backgroundTitle: 'Atlas Field Force',
      requestPermissions: true,
      stale: false,
      distanceFilter: 0,
    },
    (position, error) => {
      if (error) {
        console.error('Background location error:', error)
        return
      }
      if (position) onLocation(position)
    },
  )
}

export async function stopWatching(watcherId: string): Promise<void> {
  await BackgroundGeolocation.removeWatcher({ id: watcherId })
}

// tablet/src/location/TrackingToggle.tsx
import { useRef, useState } from 'react'
import { startWatching, stopWatching } from './backgroundLocation'
import { usePingPoster } from './usePingPoster'
import { submitPing } from '../api/pings'
import type { GeoLocation } from './backgroundLocation'

const PING_POST_INTERVAL_MS = 30_000

export function TrackingToggle() {
  const [isTracking, setIsTracking] = useState(false)
  const [lastPostedAt, setLastPostedAt] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)
  const watcherIdRef = useRef<string | null>(null)
  const latestLocationRef = useRef<GeoLocation | null>(null)

  usePingPoster(
    () => (isTracking ? latestLocationRef.current : null),
    PING_POST_INTERVAL_MS,
    (location) => {
      submitPing({
        recorded_at: new Date(location.time ?? Date.now()).toISOString(),
        latitude: location.latitude,
        longitude: location.longitude,
        accuracy: location.accuracy,
        idempotency_key: crypto.randomUUID(),
      })
        .then(() => setLastPostedAt(new Date().toLocaleTimeString()))
        .catch((err) => setError(err instanceof Error ? err.message : 'Failed to send location'))
    },
  )

  async function handleToggle() {
    setError(null)
    try {
      if (isTracking) {
        // ponytail: stopWatching is a native-bridge call and can reject too
        // (e.g. watcher already gone). Wrapped in the same try/catch as the
        // start branch so a rejection surfaces an error instead of leaving
        // isTracking/watcherIdRef stuck out of sync with reality.
        if (watcherIdRef.current) await stopWatching(watcherIdRef.current)
        watcherIdRef.current = null
        setIsTracking(false)
        return
      }
      const id = await startWatching((location) => {
        latestLocationRef.current = location
      })
      watcherIdRef.current = id
      setIsTracking(true)
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update location tracking')
    }
  }

  return (
    <div className="min-h-screen bg-gray-50 p-8">
      <h1 className="text-2xl font-semibold text-gray-900 mb-4">Atlas Field Force</h1>
      <button
        onClick={handleToggle}
        className={`px-4 py-2 rounded text-white ${isTracking ? 'bg-red-600' : 'bg-blue-600'}`}
      >
        {isTracking ? 'Stop tracking' : 'Start tracking'}
      </button>
      {lastPostedAt && <p className="mt-4 text-sm text-gray-600">Last location sent: {lastPostedAt}</p>}
      {error && <p className="mt-4 text-sm text-red-600">{error}</p>}
    </div>
  )
}
